-- Monthly checklist = the Month 2+ SOP (7 phases). Green rows in the SOP are client-facing: only those
-- show on the client report. Each task has What To Do (notes/guidance) and a Definition of Done.
-- Replaces the old deliverables list on all three packages and on months still in progress.
-- Completed (archived) months keep exactly what they recorded.

alter table public.package_items add column done_when text, add column client_facing boolean not null default false;
alter table public.report_items  add column done_when text, add column client_facing boolean not null default false;

create or replace function public.start_monthly_report(p_client uuid, p_month date)
returns uuid
language plpgsql security invoker set search_path = public as $$
declare
  m date := date_trunc('month', p_month)::date;
  rid uuid;
  pkg uuid;
begin
  if not public.is_staff() then raise exception 'not allowed'; end if;
  select id into rid from public.monthly_reports where client_id = p_client and month = m;
  if found then return rid; end if;
  select package_id into pkg from public.clients where id = p_client;
  values (p_client, m, pkg, (select name from public.packages where id = pkg), auth.uid())
  returning id into rid;
  select rid, section, name, frequency, kind, target, target_label, level, optional, notes, done_when, client_facing, position
  from public.package_items where package_id = pkg order by position;
  return rid;
end $$;
revoke execute on function public.start_monthly_report(uuid, date) from anon;

delete from public.package_items where package_id in (select id from public.packages where name in ('Search Foundation', 'Search Growth', 'Search Authority'));


-- Months still in progress switch to the new checklist (the actions log is kept).
delete from public.report_items ri using public.monthly_reports r
  where ri.report_id = r.id and r.status = 'in_progress'
    and r.package_id in (select id from public.packages where name in ('Search Foundation', 'Search Growth', 'Search Authority'));
  select r.id, pi.section, pi.name, pi.frequency, pi.kind, pi.target, pi.target_label, pi.level, pi.optional, pi.notes, pi.done_when, pi.client_facing, pi.position
  from public.monthly_reports r join public.package_items pi on pi.package_id = r.package_id
  where r.status = 'in_progress'
    and r.package_id in (select id from public.packages where name in ('Search Foundation', 'Search Growth', 'Search Authority'));
update public.monthly_reports set content_changed_at = now() where status = 'in_progress' and published_at is not null;
